function fib(n: nat): nat
  decreases n
{
  if n == 0 then 0
  else if n == 1 then 1
  else fib(n - 1) + fib(n - 2)
}

method ComputeFib(n: nat) returns (result: nat)
  ensures result == fib(n)
{
  if n == 0 {
    return 0;
  }
  var i := 1;
  var a := 0;
  var b := 1;
  while i < n
    invariant 1 <= i <= n
    invariant a == fib(i - 1)
    invariant b == fib(i)
    decreases n - i
  {
    var temp := a + b;
    a := b;
    b := temp;
    i := i + 1;
  }
  return b;
}

